window.RI1_UNITS = {"7":{"unit":7,"code":"RI1-U07","title":"WHEN DINOSAURS RULED","startNumber":189,"endNumber":209,"entries":[{"number":189,"term":"rule (v)","spoken":"rule","ipa":"rule /ruːl/","type":"verb","meaning":"thống trị","definition":"To control, govern, or have the strongest influence over a place or people.","note":"","example":"Dinosaurs ruled many land ecosystems for millions of years."},{"number":190,"term":"dig (v)","spoken":"dig","ipa":"dig /dɪɡ/","type":"verb","meaning":"đào lên…","definition":"To break, remove, or turn over earth using a tool or machine.","note":"","example":"The team dug carefully around the fossil to avoid damaging it."},{"number":191,"term":"fascinating (a) ~ interesting (a)","spoken":"fascinating , interesting","ipa":"fascinating /ˈfæsəˌneɪtɪŋ/ · interesting /ˈɪntrəstɪŋ/","type":"adjective · word family","meaning":"rất cuốn hút ~ thú vị","definition":"Extremely interesting and able to hold a person's attention.","note":"fascinating mạnh hơn interesting.","example":"The museum displayed a fascinating fossil from a dinosaur's jaw."},{"number":192,"term":"myth (n)","spoken":"myth","ipa":"myth /mɪθ/","type":"noun","meaning":"truyền thuyết, thần thoại","definition":"A traditional story used to explain beliefs, history, or natural events, often without factual proof.","note":"","example":"The discovery helped scientists challenge a popular myth about dinosaur behaviour."},{"number":193,"term":"giant (a) ~ huge (a)","spoken":"giant , huge","ipa":"giant /ˈdʒaɪənt/ · huge /hjuːdʒ/","type":"adjective · word family","meaning":"khổng lồ/rất lớn","definition":"Extremely large.","note":"giant có thể là tính từ hoặc danh từ; huge là tính từ nhấn mạnh kích thước rất lớn.","example":"The paleontologist uncovered a giant bone from a huge dinosaur."},{"number":194,"term":"paleontologist (n)","spoken":"paleontologist","ipa":"paleontologist /ˌpeɪliəˈntɑːlədʒɪst/","type":"noun","meaning":"nhà cổ sinh vật học","definition":"A scientist who studies fossils to understand life in the distant past.","note":"","example":"A paleontologist studies fossils to understand prehistoric life."},{"number":195,"term":"fairly (adv) ~ quite (adv)","spoken":"fairly , quite","ipa":"fairly /ˈfɛrli/ · quite /kwaɪt/","type":"adverb · word family","meaning":"khá/tương đối","definition":"To a moderate degree; quite can be similar but may be stronger depending on context.","note":"fairly thường mang nghĩa khá; quite có thể mạnh hơn tùy từ đi sau.","example":"The fossil was fairly complete and quite well preserved."},{"number":196,"term":"predator (n) >< prey (n)","spoken":"predator , prey","ipa":"predator /ˈprɛdətɚ/ · prey /preɪ/","type":"noun · noun · word family","meaning":"động vật săn mồi >< con mồi","definition":"A predator hunts other animals for food; its prey is the animal being hunted.","note":"Dấu >< chỉ cặp từ trái nghĩa; học cả hai chiều để nhận biết trong văn cảnh.","example":"A predator hunts other animals, while prey must avoid being caught."},{"number":197,"term":"scavenger (n)","spoken":"scavenger","ipa":"scavenger /ˈskævəndʒɚ/","type":"noun","meaning":"thú ăn xác thối","definition":"An animal that feeds on dead animals or discarded organic matter.","note":"","example":"A scavenger feeds on animals that are already dead."},{"number":198,"term":"descendant (n)","spoken":"descendant","ipa":"descendant /dɪˈsɛndənt/","type":"noun","meaning":"con cháu, hậu duệ","definition":"A person, animal, or plant related to an earlier ancestor through later generations.","note":"","example":"Modern birds are descendants of a group of small dinosaurs."},{"number":199,"term":"relative (n) # relation (n) · relationship (n) · relate (v) to","spoken":"relative , relation , relationship , relate to","ipa":"relative /ˈrɛlətɪv/ · relation /riˈleɪʃən/ · relationship /riˈleɪʃəˌnʃɪp/ · relate /rɪˈleɪt/","type":"verb · noun · word family","meaning":"họ hàng/người thân # mối liên hệ · mối quan hệ · có liên quan đến","definition":"To be connected with; connected; a family member; a connection between people.","note":"relation nghĩa là mối liên hệ/quan hệ; relative nghĩa là họ hàng; relationship nghĩa là mối quan hệ; relate to nghĩa là có liên quan đến.","example":"My closest relative is my aunt, and I have a good relationship with her. We are related, and our interests relate to music."},{"number":200,"term":"decay (v,n)","spoken":"decay","ipa":"decay /dɪˈkeɪ/","type":"verb · noun","meaning":"thối rữa, phân hủy","definition":"To gradually break down or rot; decay is also the process of breaking down.","note":"","example":"Soft tissue decays quickly, so this type of fossil is extremely rare."},{"number":201,"term":"die out (v) ~ be extinct (a)","spoken":"die out , be extinct","ipa":"die /daɪ/ · out /aʊt/ · extinct /ɪˈkstɪŋkt/","type":"phrasal verb · adjective · word family","meaning":"tuyệt chủng/không còn tồn tại","definition":"To disappear completely as a species; to become extinct.","note":"die out là động từ; extinct là tính từ: dinosaurs died out · dinosaurs are extinct.","example":"Many dinosaur species died out after a major change in the environment."},{"number":202,"term":"extinct (a) · extinction (n)","spoken":"extinct , extinction","ipa":"extinct /ɪˈkstɪŋkt/ · extinction /ɪˈkstɪŋkʃən/","type":"noun · adjective · word family","meaning":"đã tuyệt chủng · sự tuyệt chủng","definition":"No longer existing; the complete disappearance of a species.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Dinosaurs are extinct, and their extinction happened millions of years ago."},{"number":203,"term":"in reality ~ in fact","spoken":"in reality , in fact","ipa":"reality /ˌriˈæləˌti/ · fact /fækt/","type":"phrase / pattern · word family","meaning":"trên thực tế","definition":"Used to describe what is actually true, rather than what appears or is believed.","note":"in fact bổ sung hoặc sửa thông tin; in reality đối chiếu với điều người ta tưởng là đúng.","example":"In reality, not every large dinosaur was a dangerous predator."},{"number":204,"term":"estimate (v)","spoken":"estimate","ipa":"estimate /ˈɛstəmeɪt/","type":"verb","meaning":"ước tính, ước lượng","definition":"To make an approximate calculation.","note":"","example":"Scientists estimate that the test will take two hours."},{"number":205,"term":"perhaps ~ probably ~ possibly","spoken":"perhaps , probably , possibly","ipa":"perhaps /pɚˈhæps/ · probably /ˈprɑːbəˌbli/ · possibly /ˈpɑːsəbli/","type":"adverb · adverb · adverb · word family","meaning":"có lẽ ~ rất có thể ~ có thể","definition":"Perhaps, probably, and possibly all express uncertainty, but probably shows greater likelihood.","note":"probably chỉ khả năng cao hơn perhaps và possibly.","example":"Perhaps the animal hunted alone, although it probably also searched for food in groups."},{"number":206,"term":"limb (n)","spoken":"limb","ipa":"limb /lɪm/","type":"noun","meaning":"chi (tay/chân)","definition":"An arm or leg of a person or animal, or a large branch of a tree.","note":"","example":"The fossilized limb shows how the dinosaur moved across soft ground."},{"number":207,"term":"branch (n)","spoken":"branch","ipa":"branch /bræntʃ/","type":"noun","meaning":"cành cây","definition":"A part of a tree growing from its trunk; also a division of an organization or subject.","note":"","example":"Birds form one surviving branch of the dinosaur family tree."},{"number":208,"term":"solve (v) ~ deal with ~ cope with","spoken":"solve , deal with , cope with","ipa":"solve /sɑːlv/ · deal /diːl/ · cope /koʊp/","type":"verb · phrasal verb · phrasal verb · word family","meaning":"giải quyết, xử lí hoặc ứng phó với","definition":"To find an answer to a problem, or to manage and respond to a difficult situation.","note":"solve là giải quyết được vấn đề; deal with/cope with là xử lí hoặc ứng phó.","example":"Scientists solved part of the mystery, but they still need to deal with several gaps in the evidence."},{"number":209,"term":"brief (a)","spoken":"brief","ipa":"brief /briːf/","type":"adjective","meaning":"ngắn gọn","definition":"Short in length or duration and containing only the main points.","note":"","example":"The report gives a brief explanation of how the fossil was discovered."}],"pronunciationFocus":[{"entryNumber":191,"points":[{"category":"common-error","note":"interesting /ˈɪntrəstɪŋ/: giữ đúng cụm /tr/ và không chèn thêm nguyên âm"}]},{"entryNumber":194,"points":[{"category":"word-stress","note":"paleontologist /ˌpeɪliəˈntɑːlədʒɪst/: trọng âm chính rơi vào /ˈntɑː/"}]},{"entryNumber":202,"points":[{"category":"final-sound","note":"extinct /ɪˈkstɪŋkt/: giữ đủ cụm /ŋkt/ ở cuối"}]},{"entryNumber":206,"points":[{"category":"silent-letter","note":"limb /lɪm/: chữ b cuối từ không được phát âm"}]},{"entryNumber":207,"points":[{"category":"final-sound","note":"branch /bræntʃ/: giữ đủ cụm /ntʃ/ ở cuối"}]}]}};
